import assert from 'node:assert/strict';
import{readFile,writeFile}from'node:fs/promises';
import{resolve,join}from'node:path';
import{pathToFileURL}from'node:url';
const dir=resolve(process.argv[2]);
const {metadata}=await import(pathToFileURL(join(dir,'program.mjs')).href);
const weights=metadata.functions.find(f=>f.name==='initial_weights').index;
let code=await readFile(join(dir,'program.mjs'),'utf8');
const pattern=new RegExp('function __fn'+weights+'\\([^)]*\\)\\{');
assert(pattern.test(code));
code=code.replace(pattern,m=>m+'globalThis.__defaultWeightBuilds++;');
await writeFile(join(dir,'instrumented.mjs'),code);
globalThis.__defaultWeightBuilds=0;
const {createState}=await import(pathToFileURL(join(dir,'instrumented.mjs')).href);
const state=createState(),features=Array(10).fill(0.2),target=Array(4).fill(0.1);
assert.equal(globalThis.__defaultWeightBuilds,0);
const predict=()=>state.invoke('predict',[features]).result;
const first=predict();assert.equal(globalThis.__defaultWeightBuilds,1);
assert.deepEqual(predict(),first);assert.equal(globalThis.__defaultWeightBuilds,1);
assert(state.invoke('observe',[features,target,2]).committed);
const learned=predict();assert.notDeepEqual(learned,first);assert.equal(globalThis.__defaultWeightBuilds,1);
const model=state.invoke('model',[]).result;model.Ok.weights.fill(99);assert.deepEqual(predict(),learned);
const before=await state.checkpoint();assert.equal(state.invoke('cancel',[features,target]).committed,false);
assert.deepEqual(await state.checkpoint(),before);assert.deepEqual(predict(),learned);assert.equal(globalThis.__defaultWeightBuilds,1);
state.beginTransaction();assert(state.invoke('observe',[features,target,2]).committed);state.rollbackTransaction();
assert.deepEqual(predict(),learned);assert.equal(globalThis.__defaultWeightBuilds,1);
await state.restore(before);assert.equal(globalThis.__defaultWeightBuilds,1);assert.deepEqual(predict(),learned);assert.equal(globalThis.__defaultWeightBuilds,2);
console.log('Prepared defaults: one weight initialization through predictions, training, rollback and private outputs; explicit restore rebuilds once.');
